-- CREATE/DEFINE VIEW with a DATA_METRIC_SCHEDULE
-- https://docs.snowflake.com/en/sql-reference/sql/create-view

CREATE OR REPLACE VIEW v
DATA_METRIC_SCHEDULE = '60 MINUTE'
AS
SELECT 1 AS a;

DEFINE VIEW DCM_PROJECT.ANALYTICS.V_METRIC_SCHEDULE
DATA_METRIC_SCHEDULE = '5 minutes'
AS
SELECT a FROM b;
